#!/usr/bin/env python3
"""Compute ground truth for CSX-192_Q1 without point-weather dependence."""

from __future__ import annotations

import html
import json
import math
import re
from pathlib import Path


TASK_ID = "CSX-192_Q1"
EVENT_ID = "CSX-192"
HIGH_LEDGER_THRESHOLD = 3



REASONING_DEPTH = {'evidence_weighting': 'The report anchor and ERA5 heat context pass, but wind and dNBR checks are decisive negative tests for the high-threshold screen.', 'counterfactual_rejection': 'A high-threshold wildfire answer fails because only two of four component tests pass and the dNBR summary remains weak mixed.', 'uncertainty_or_scale_caveat': 'The failed wind and burn-summary thresholds do not deny severe reported impacts; they only bound this specific numeric screen.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def read_json(path: Path):
    return json.loads(read_text(path))


def strip_tags(fragment: str) -> str:
    text = re.sub(r"<[^>]+>", "", fragment)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def article_text(path: Path) -> str:
    raw = read_text(path)
    paragraphs = [strip_tags(match) for match in re.findall(r"<p>(.*?)</p>", raw, re.S)]
    return " ".join(paragraphs)


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    report_rel = "data/event_reports/event_reports_001_Locked_anchor_report_NASA_Earth_Observatory.html"
    era5_rel = "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json"
    dnbr_rel = "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json"

    text = article_text(package_dir / report_rel)
    evacuated_people = 10000 if re.search(r"Ten thousand people were evacuated", text, re.I) else None
    destroyed_houses_lower_bound = (
        500 if re.search(r"more than 500 houses were destroyed", text, re.I) else None
    )
    era5 = read_json(package_dir / era5_rel)
    dnbr = read_json(package_dir / dnbr_rel)
    stats = era5["stats"]
    era5_peak_tmax_c = float(stats["temperature_2m_max_c_max"])
    era5_mean_tmax_c = float(stats["temperature_2m_max_c_mean"])
    wind_u = float(stats["u_component_of_wind_10m_mean"])
    wind_v = float(stats["v_component_of_wind_10m_mean"])
    mean_wind_speed_mps = math.hypot(wind_u, wind_v)
    dnbr_mean = float(dnbr["stats"]["sentinel2_dnbr_mean"])
    dnbr_max = float(dnbr["stats"]["sentinel2_dnbr_max"])

    tests = {
        "report_anchor": (
            evacuated_people is not None
            and evacuated_people >= 10000
            and destroyed_houses_lower_bound is not None
            and destroyed_houses_lower_bound >= 500
        ),
        "gridded_heat_context": era5_peak_tmax_c >= 34.0 and era5_mean_tmax_c >= 32.0,
        "gridded_wind_context": mean_wind_speed_mps >= 1.0,
        "positive_burn_summary": dnbr_mean >= 0.0 and dnbr_max >= 0.300,
    }
    passed_tests = [name for name, passed in tests.items() if passed]
    failed_tests = [name for name, passed in tests.items() if not passed]
    score = len(passed_tests)
    high_threshold_met = score >= HIGH_LEDGER_THRESHOLD
    dnbr_state = "positive" if tests["positive_burn_summary"] else "weak_mixed"

    primary_gt = {
        "score": f"{score}/4",
        "high_threshold_met": high_threshold_met,
        "era5_peak_tmax_c": round(era5_peak_tmax_c, 1),
        "era5_mean_tmax_c": round(era5_mean_tmax_c, 1),
        "era5_mean_wind_speed_mps": round(mean_wind_speed_mps, 3),
        "dnbr_state": dnbr_state,
        "passed_tests": passed_tests,
        "failed_tests": failed_tests,
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "western_cape_report_gridded_burn_threshold_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "report_metrics": {
                "evacuated_people": evacuated_people,
                "destroyed_houses_lower_bound": destroyed_houses_lower_bound,
            },
            "era5_stats": {
                "peak_tmax_c": era5_peak_tmax_c,
                "mean_tmax_c": era5_mean_tmax_c,
                "mean_wind_u_mps": wind_u,
                "mean_wind_v_mps": wind_v,
                "mean_wind_speed_mps": mean_wind_speed_mps,
            },
            "burn_metrics": {
                "dnbr_mean": dnbr_mean,
                "dnbr_max": dnbr_max,
                "dnbr_state": dnbr_state,
            },
            "ledger": {
                "tests": tests,
                "passed_tests": passed_tests,
                "failed_tests": failed_tests,
                "score": score,
                "score_text": f"{score}/4",
                "high_threshold_met": high_threshold_met,
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [report_rel, era5_rel, dnbr_rel],
            "notes": "Open-Meteo point weather is intentionally not used.",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final ledger result",
                    "points": 4,
                    "description": "Reports score 2/4 and high_threshold_met false in the requested JSON structure.",
                    "partial_credit": "Award 1-3 points for the right pass count with one missing field.",
                },
                {
                    "name": "Report anchor",
                    "points": 4,
                    "description": "Uses 10,000 evacuees and the house-destruction lower bound of 500 to pass the report anchor.",
                    "partial_credit": "Award 2 points for each correct report threshold.",
                },
                {
                    "name": "ERA5 heat context",
                    "points": 4,
                    "description": "Computes ERA5 peak Tmax about 34.4 C and mean Tmax about 32.6 C, passing the heat context test.",
                    "partial_credit": "Award 2 points for each correct temperature anchor.",
                },
                {
                    "name": "ERA5 wind context",
                    "points": 3,
                    "description": "Computes mean wind-vector speed about 0.357 m/s and correctly fails the 1.0 m/s wind test.",
                    "partial_credit": "Award 1-2 points for component extraction or speed formula.",
                },
                {
                    "name": "dNBR threshold test",
                    "points": 3,
                    "description": "Uses mean -0.016995 and maximum 0.294351 to label the burn summary weak_mixed.",
                    "partial_credit": "Award 1-2 points for using only one dNBR threshold correctly.",
                },
                {
                    "name": "Output discipline",
                    "points": 2,
                    "description": "Returns compact JSON and does not add unrequested precipitation, health, or loss estimates.",
                    "partial_credit": "Award 1 point for correct numeric result in an incomplete structure.",
                },
            ],
        },
    }

    attach_reasoning_depth(output)
    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
